        double angle = 2 * std::acos(-1.0) * i / numberOfChecks;
        Point3d direction(std::cos(angle), std::sin(angle), 0);
        Point3d end = p + 1000.0 * direction; // arbitrary large distance
        rays.push_back(std::make_pair(p, end));
    }
    int intersections = 0;
    for (const auto& ray : rays) {
        std::vector<CGAL::Object> result;
        tree.all_intersections(ray.first, ray.second, std::back_inserter(result));
        if (result.size() % 2 != 0) {
            intersections++;
        }
    }
    return intersections > 0;

